import{_ as a,o as e,c as i,a5 as t}from"./chunks/framework.CcrBcQWS.js";const k=JSON.parse('{"title":"Image Echo — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/image-echo.md","filePath":"ko/software/sdk/cpp/image-echo.md","lastUpdated":1787021357000}'),n={name:"ko/software/sdk/cpp/image-echo.md"};function o(l,s,p,h,c,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="image-echo-—-c-예제" tabindex="-1">Image Echo — C++ 예제 <a class="header-anchor" href="#image-echo-—-c-예제" aria-label="Permalink to &quot;Image Echo — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_image_echo.cpp</code></p><p>압축 카메라 토픽을 <strong>구독</strong>해 초당 수신율, 마지막 프레임 크기, 이미지 포맷을 출력하는 읽기 전용 진단 도구입니다. 카메라 스트림이 실제로 발행되고 있는지, SDK 호스트에서 도달 가능한지 확인할 때 사용합니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><p>프로그램 동작:</p><ol><li><code>argv[1]</code>에서 토픽 이름을 읽습니다 (기본값 <code>rt/rbq/vision/sensor_4/rgb/compressed</code>).</li><li>DDS <code>ChannelFactory</code>를 초기화하고 <code>Subscriber&lt;CompressedImage_&gt;</code>를 생성합니다.</li><li>샘플을 수신할 때마다 카운터, 마지막 바이트 크기, 이미지 포맷을 갱신합니다.</li><li>1초마다 경과 시간, 총 샘플 수, 1초 수신율, 마지막 프레임 크기, 포맷을 출력합니다.</li><li><code>Ctrl+C</code>(SIGINT/SIGTERM) 시 총 샘플 수를 출력하고 정상 종료합니다.</li></ol><p>발행은 하지 않으므로 실제 로봇이나 시뮬레이터와 함께 실행해도 안전합니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>압축 이미지 토픽을 발행하는 측이 실행 중이어야 합니다 — 로봇 비전 스택 또는 비전 포함 MuJoCo 시뮬레이터(<code>bash scripts/sim.bash --vision</code>).</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin/rbq_image_echo</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><h3 id="실제-로봇에서" tabindex="-1">실제 로봇에서 <a class="header-anchor" href="#실제-로봇에서" aria-label="Permalink to &quot;실제 로봇에서&quot;">​</a></h3><p>기본값이 로봇에 맞춰져 있으므로 그대로 실행하면 됩니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span></span></code></pre></div><p>로봇의 <code>enp45s0</code> 인터페이스로 <code>rt/rbq/vision/sensor_4/rgb/compressed</code>(전방 카메라)을 구독합니다 — 인터페이스(<code>main()</code>의 <code>ChannelFactory::Instance().Init(0, &quot;enp45s0&quot;)</code>)와 기본 토픽 모두 예제에 내장돼 있습니다. 다른 카메라를 보려면 토픽을 첫 번째 인자로 전달하세요.</p><h3 id="mujoco-시뮬레이터에서" tabindex="-1">MuJoCo 시뮬레이터에서 <a class="header-anchor" href="#mujoco-시뮬레이터에서" aria-label="Permalink to &quot;MuJoCo 시뮬레이터에서&quot;">​</a></h3><p>시뮬레이터는 로봇이 아니라 본인 PC에서 동작하므로 두 가지가 달라집니다.</p><p><strong>1. 실제로 존재하는 인터페이스로 심을 띄우세요.</strong> <code>-i</code> 없이 <code>sim.bash --vision</code>을 실행하면 비전/카메라 발행 측이 로봇의 <code>enp45s0</code>에 뜨는데, 이 인터페이스는 본인 PC에 없어서 클라이언트가 아무것도 못 받습니다. <code>ip link</code>로 인터페이스를 확인해(예: <code>enp3s0</code>) 전달하면 심 전체가 그 인터페이스를 공유합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span></code></pre></div><p><strong>2. 이 클라이언트를 같은 인터페이스로 맞춘 뒤 실행하세요.</strong> 인터페이스가 소스에 하드코딩돼 있으니 CycloneDDS 설정으로 덮어씁니다. SDK는 <code>CYCLONEDDS_URI</code>가 설정돼 있을 때만 그 값을 쓰므로 <strong>먼저 파일을 만들어야 합니다</strong>(<code>enp3s0</code>을 본인 인터페이스로 교체):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/cyclonedds.xml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot; ?&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;CycloneDDS xmlns=&quot;https://cdds.io/config&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &lt;Domain Id=&quot;any&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;General&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;Interfaces&gt;&lt;NetworkInterface name=&quot;enp3s0&quot; priority=&quot;default&quot; multicast=&quot;default&quot;/&gt;&lt;/Interfaces&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;AllowMulticast&gt;spdp&lt;/AllowMulticast&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;/General&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &lt;/Domain&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/CycloneDDS&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CYCLONEDDS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file:///tmp/cyclonedds.xml</span></span></code></pre></div><p>그런 다음 실행하세요. 카메라는 로봇·심 모두 <strong>숫자 id</strong>를 씁니다 — <code>sensor_4</code>가 전방, <code>sensor_5</code>가 후방 카메라입니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 전방 카메라</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_5/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 후방 카메라</span></span></code></pre></div><p><code>sensor_4</code>가 <strong>전방</strong>, <code>sensor_5</code>가 <strong>후방</strong> 카메라입니다. <code>sensor_0</code>–<code>sensor_3</code>은 <code>depth</code>와 <code>ir</code>만 발행합니다.</p><blockquote><p>심과 이 클라이언트는 <strong>같은</strong> 인터페이스를 써야 합니다 — 다르거나, 둘 다 <code>lo</code>(보통 멀티캐스트 미지원)에 두면 <code>rate=0 Hz</code>가 됩니다.</p></blockquote><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><p>MuJoCo 시뮬레이터(<code>sim.bash --vision</code>)에서 <code>sensor_4</code>(전방 카메라)를 구독한 결과:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_image_echo] subscribed to &#39;rt/rbq/vision/sensor_4/rgb/compressed&#39;</span></span>
<span class="line"><span>[rbq_image_echo] waiting for samples (Ctrl+C to exit)...</span></span>
<span class="line"><span>[rbq_image_echo] 1.0s  total=15  rate=15 Hz  last=13053 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 2.0s  total=29  rate=14 Hz  last=13080 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 3.0s  total=44  rate=15 Hz  last=13067 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] exiting, total samples = 44</span></span></code></pre></div><p>수신율이 일정하고 바이트 크기가 0이 아니며 <code>fmt=&#39;jpeg&#39;</code>이면 스트림이 정상입니다. <code>rate=0 Hz</code>이면 해당 토픽/인터페이스에서 발행 측을 찾지 못한 것이니 토픽 이름과 DDS 인터페이스를 확인하세요.</p>`,32)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
